export type MessageKey = string;

interface I18nContextValue {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: MessageKey, vars?: Record<string, string | number>) => string;
}

const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const { language, setLanguage } = useLanguage();
  const locale: Locale = language === 'en-US' ? 'en' : language === 'es-ES' ? 'es' : 'pt';

  const setLocale = useCallback((next: Locale) => {
    setLanguage(next === 'en' ? 'en-US' : next === 'es' ? 'es-ES' : 'pt-BR');
  }, [setLanguage]);

  const t = useCallback((key: MessageKey, vars?: Record<string, string | number>) => {
    let text: string = MESSAGES[locale][key as keyof typeof MESSAGES.pt]
      ?? (locale === 'pt' ? key : LITERAL_MESSAGES[locale][key as keyof (typeof LITERAL_MESSAGES)[typeof locale]] ?? key);
    if (vars) {
      for (const [name, value] of Object.entries(vars)) {
        text = text.replaceAll(`{${name}}`, String(value));
      }
    }
    return text;
  }, [locale]);

  const value = useMemo(() => ({ locale, setLocale, t }), [locale, setLocale, t]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useI18n deve ser usado dentro de <I18nProvider>');
  }
  return context;
}
